const payload = msg.payload;
const isBackfill = payload.backfill === true;

// Extract device_id from MQTT topic (hivis/<device_id>/data) if not in payload
const deviceId   = (payload.device_id   || msg.topic.split('/')[1] || "unknown").toString();
const deviceName = (payload.device_name || deviceId).toString();

const ts = (isBackfill && payload.ts > 0) ? payload.ts * 1000 : Date.now();

// node-red-contrib-influxdb 0.7 + InfluxDB 2.0 format: [fieldsObj, tagsObj]
msg.measurement = "air_quality";
msg.payload = [
    {
        temp:     payload.temp,
        hum:      payload.hum,
        iaq:      payload.iaq,
        co2:      payload.co2,
        bvoc:     payload.bvoc,
        db:       payload.db,
        bat_pct:  payload.bat_pct,
        bat_mv:   payload.bat_mv,
        rssi:     payload.rssi,
        accuracy: payload.accuracy,
        time:     ts
    },
    {
        device_id:   deviceId,
        device_name: deviceName,
        group:       payload.group || "default",
        backfill:    String(isBackfill)
    }
];

return msg;

const reg = msg.payload;
const mac = reg.mac.toLowerCase().replace(/:/g, "");
const fs = require("fs");

let whitelist;
try {
    whitelist = JSON.parse(fs.readFileSync("/data/whitelist.json", "utf8"));
} catch (e) {
    node.error("Cannot read whitelist.json: " + e.message, msg);
    return null;
}

const device = whitelist.devices.find(d =>
    d.mac.toLowerCase().replace(/:/g, "") === mac
);

if (device && device.authorized) {
    msg.approved = true;
    msg.mac = mac;
    msg.device_name = reg.device_name;
} else {
    msg.approved = false;
    msg.mac = mac;
}
return msg;

const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
let pass = "";
for (let i = 0; i < 20; i++) {
    pass += chars[Math.floor(Math.random() * chars.length)];
}

const user = "device_" + msg.mac;
const deviceId = "hivis-" + msg.mac;

// Output 1: MQTT retain message to provision the device
const mqttMsg = {
    topic: "hivis/provision/" + msg.mac,
    payload: JSON.stringify({
        status: "approved",
        mqtt_user: user,
        mqtt_pass: pass,
        device_id: deviceId
    }),
    retain: true
};

// Output 2: HTTP POST to OTA server to update Mosquitto passwd + ACL
const httpMsg = {
    payload: JSON.stringify({ user: user, password: pass }),
    headers: {
        "Content-Type": "application/json",
        "X-Provision-Token": "_QYf_IIpIc3WAQMmWskCj0Zrfeeasjmx1irFq7aoi0M"
    }
};

return [mqttMsg, httpMsg];

msg.topic = "hivis/provision/" + msg.mac;
msg.payload = JSON.stringify({
    status: "rejected",
    device_id: "hivis-" + msg.mac
});
msg.retain = false;
return msg;

const payload = msg.payload;
const isBackfill = payload.backfill === true;

// Extract device_id from MQTT topic (hivis/<device_id>/data) if not in payload
const deviceId   = (payload.device_id   || msg.topic.split('/')[1] || "unknown").toString();
const deviceName = (payload.device_name || deviceId).toString();

const ts = (isBackfill && payload.ts > 0) ? payload.ts * 1000 : Date.now();

// node-red-contrib-influxdb 0.7 + InfluxDB 2.0 format: [fieldsObj, tagsObj]
msg.measurement = "device_status";
msg.payload = [
    {
        bat_pct:    payload.bat_pct,
        bat_mv:     payload.bat_mv,
        rssi:       payload.rssi,
        accuracy:   payload.accuracy,
        fw_version: payload.fw_version || "unknown",
        time:       ts
    },
    {
        device_id:   deviceId,
        device_name: deviceName,
        group:       payload.group || "default"
    }
];

return msg;
